INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (52, '1194d095-a9e1-11f1-adb3-5612c5722cec', 'Ação', 'Cenas de luta intensas, combates épicos e protagonistas que encaram desafios físicos com coragem e determinação.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (53, '1194d6be-a9e1-11f1-adb3-5612c5722cec', 'Aventura', 'Histórias épicas de jornadas, exploração de mundos desconhecidos e descobertas de tesouros e segredos.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (54, '1194d864-a9e1-11f1-adb3-5612c5722cec', 'Artes Marciais', 'Foco em estilos de luta como karatê, judô, kung fu e técnicas de combate corpo a corpo.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (55, '1194d97f-a9e1-11f1-adb3-5612c5722cec', 'Comédia', 'Situações engraçadas, personagens caricatos e humor que faz o público rir. Exemplos clássicos incluem Gintama e Konosuba.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (56, '1194da83-a9e1-11f1-adb3-5612c5722cec', 'Drama', 'Narrativas profundas que exploram emoções humanas, conflitos internos e relações interpessoais complexas.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (57, '1194dc61-a9e1-11f1-adb3-5612c5722cec', 'Escola', 'Ambientado em escolas japonesas com foco em cotidiano de estudantes, amizades e romance.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (58, '1194dd87-a9e1-11f1-adb3-5612c5722cec', 'Esportes', 'Competições atléticas como futebol, basquete, tênis e natação com momentos de superação.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (59, '1194de81-a9e1-11f1-adb3-5612c5722cec', 'Fantasia', 'Mundos mágicos com criaturas sobrenaturais, magias e aventuras em reinos fictícios.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (60, '1194e02f-a9e1-11f1-adb3-5612c5722cec', 'Ficção Científica', 'Futuros distópicos, tecnologias avançadas, viagens no tempo e alienígenas.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (61, '1194e107-a9e1-11f1-adb3-5612c5722cec', 'Horror', 'Histórias de terror que provocam medo e suspense com elementos sobrenaturais e psicológicos.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (62, '1194e1e3-a9e1-11f1-adb3-5612c5722cec', 'Isekai', 'Protagonistas transportados para outros mundos, geralmente com poderes especiais.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (63, '1194e2d9-a9e1-11f1-adb3-5612c5722cec', 'Jogo', 'Baseados em jogos de RPG, MMOs ou jogos de cartas colecionáveis.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (64, '1194e3ce-a9e1-11f1-adb3-5612c5722cec', 'Magical Girl', 'Garotas que ganham poderes mágicos e lutam contra forças do mal com transformações espectaculares.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (65, '1194e50e-a9e1-11f1-adb3-5612c5722cec', 'Mecha', 'Robôs gigantes pilotados por humanos em batalhas épicas contra alienígenas ou inimigos.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (66, '1194e5f5-a9e1-11f1-adb3-5612c5722cec', 'Mistério', 'Enigmas para resolver, crimes para desvendar e segredos para descobrir.', 'ATIVO');
