INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (69, '1194e855-a9e1-11f1-adb3-5612c5722cec', 'Romance', 'Histórias de amor entre personagens, com sentimentalismo e desenvolvimento de relacionamentos.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (70, '1194e951-a9e1-11f1-adb3-5612c5722cec', 'Sci-Fi', 'Ficção científica com elementos tecnológicos, viagens espaciais e futuros imaginários.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (71, '1194ea41-a9e1-11f1-adb3-5612c5722cec', 'Seinen', 'Voltado para adultos jovens com temas maduros, violência realista e complexidade narrativa.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (72, '1194eb0d-a9e1-11f1-adb3-5612c5722cec', 'Shojo', 'Voltado para garotas com foco em romance, amizade e crescimento pessoal.', 'ATIVO');
INSERT INTO genero (id, uuid, nome, descricao, status_desc) VALUES (73, '1194ec05-a9e1-11f1-adb3-5612c5722cec', 'Shonen', 'Voltado para garotos com foco em amizade, superação e batalhas épicas.', 'ATIVO');
